export interface Member {
  id: string;
  name: string;
  kind: 'team' | 'person';
  /** People only. */
  role?: string;
  /** Can't move, and takes no one in. */
  locked?: boolean;
  /** A team's members: the tree's children live here, not in `children`. */
  members?: Member[];
}

const person = (id: string, name: string, role: string, locked?: boolean): Member => ({
  id,
  name,
  role,
  kind: 'person',
  locked,
});

